        cause="損害賠償請求事件",
        result="上告棄却",
        cites=["集民176号563頁", "判時1546号115頁", "判タ891号77頁", "労判680号28頁"],
        issue="特定の政党の党員等であることのみを理由とする職場内外での継続的な監視や孤立化が不法行為となるか",
