        summary='採用時の健康診断で採取された血液を用い、本人の同意を得ずにＨＩＶ抗体検査が行われた事案。東京地裁は、感染情報は他人に知られたくない性質の情報であり、本人の意思に反して取得することは原則としてプライバシーを侵害する違法な行為であるとして、損害賠償を認めた。',
