        summary='飲食店に勤務していた社員が長時間労働の後に死亡した事案。大阪高裁は、会社の責任に加え、取締役について、社員の生命と健康を守る勤務体制を整え長時間労働を是正する措置を講じる点で任務を怠ったとして、個人としての賠償責任を認めた。',
