        docket='平成7年（オ）第1299号',
        cause='地位確認、社宅明渡請求事件',
        result='棄却',
        cites=['集民182号673頁', '労判713号27頁', '判時1607号131頁'],
        issue='労働条件を不利益に変更する労働協約の規範的効力',
