        cites=['労判722号62頁', '労民集48巻4号312頁', '判タ957号196頁'],
        issue='販売主任の管理監督者性、展覧会での展示販売に事業場外みなし労働時間制が適用されるか、休日振替の要件、黙示の指示による休日労働',
